window.RP_SESSION={"id":"S-d2b829a86d1a","messages":[{"id":"RP-II-0117907","time":"2026-07-17T15:40:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"손이 닿는가?\"\n\n당신은 코난의 어깨에 발을 딪고 일어선 상태입니다. 코난은 당신이 넘어지지 않도록 종아리 뼈를 단단히 붙잡고 있는 상태입니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117908","time":"2026-07-17T15:41:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"@베어","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117909","time":"2026-07-17T15:42:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"잠깐만요.. 쪼오오끔만..\"\n아마이 조가 낑낑거리며, 팔을 최대한 쭉 뻗어봅니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117910","time":"2026-07-17T15:42:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"방향은 맞나? 조금 움직일 필요는 없는가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117911","time":"2026-07-17T15:42:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"쓰읍.. 살짝 더 왼쪽으로 가주실래요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117912","time":"2026-07-17T15:43:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"몇 발자국을 말인가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117913","time":"2026-07-17T15:43:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"한.. 한 발자국보다 좀 적게, 반 발자국?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117914","time":"2026-07-17T15:43:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 코난의 보폭으로 반발자국 움직입니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117915","time":"2026-07-17T15:44:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"오, 오오오..!\"\n조가 기우뚱거리며 중심을 잡습니다.\n\"좋아요, 딱 여기에요..!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117916","time":"2026-07-17T15:45:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"좋아, 쟈리엘 꽃이 얼마나 있지? 그보다 그림에 그려진 것과 같은 모양인가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117917","time":"2026-07-17T15:46:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"흠.. 제가 보기엔 같은 것 같네요. 다만 몇 송이 없어요..\"\n조가 꽃 바로 앞에 손을 대고 말합니다.\n\"딸까요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117918","time":"2026-07-17T15:47:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"일단 따고 살펴본다. 분명 주머니에 가득 찰 정도만 챙겨오면 된다고 했으니까.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117919","time":"2026-07-17T15:48:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"조가 하나 둘 꽃을 따기 시작합니다.\n\"흠, 한 송이 정돈 남겨둘까.\"\n그래도 한손엔 가득 쥘 만큼 따고, 코난에게 건네줍니다.\n\"어때요, 더 필요할 것 같나요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117920","time":"2026-07-17T15:49:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"얼마나 필요할지 운명으로 확인해볼까요?","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117921","time":"2026-07-17T15:49:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117922","time":"2026-07-17T15:49:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 5 = 5\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0117923","time":"2026-07-17T15:49:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 꽃을 지급받은 주머니에 넣어보고서는 말합니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117924","time":"2026-07-17T15:49:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"좀 모자란 것 같은데.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117925","time":"2026-07-17T15:49:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"비슷한 군체를 하나 더 찾아야한다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117926","time":"2026-07-17T15:49:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"이번처럼 절벽을 쭉 따라가 걷다보면 나올 것이다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117927","time":"2026-07-17T15:50:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"느엑, 어쩔 수 없군요..\"\n우선 마저 한 송이를 따 건네줍니다.\n\"또 다른 녀석들을 향해 가볼까요!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117928","time":"2026-07-17T15:50:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"좋다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117929","time":"2026-07-17T15:51:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그나저나 갑자기 이렇게 불려와두고 사과를 하지 않았다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117930","time":"2026-07-17T15:51:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"미안하다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117931","time":"2026-07-17T15:51:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"의뢰비는 당연히 반반 나눌 예정이다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117932","time":"2026-07-17T15:51:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"에이, 괜찮아요 괜찮아! 마침 저도 할 일도 없고 돈도 필요했어서 말이죠~!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117933","time":"2026-07-17T15:52:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그렇다면 다행이다. 다른 사람들 없었다. 언데드, 떨어져도 덜 다치고 가볍다. 이번 의뢰에 적합하다고 생각해서 데리고 나왔다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117934","time":"2026-07-17T15:52:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 확실히 이 절벽, 아래가 참 까마득한게 안전해보이진 않네요..\"\n키가 큰 코난의 어깨에 올라와 있기에 괜히 더욱 더 높이감이 크게 다가왔다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117935","time":"2026-07-17T15:53:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"저만큼 적절한 사람이 또 없죠, 암!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117936","time":"2026-07-17T15:53:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"아래로 내려가지는 않을 예정이다. 간단한 의뢰에 목숨을 걸 수는 없으니까. 우리는 이렇게 손으로 닿을만한 것들만 가져간다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117937","time":"2026-07-17T15:54:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"흠, 저기 저것도 쟈리엘 꽃인가..?\"\n인상을 찌푸리며 살펴보다 한 곳을 가리킵니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117938","time":"2026-07-17T15:55:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"운명으로 점쳐볼까요?","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117939","time":"2026-07-17T15:55:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117940","time":"2026-07-17T15:55:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 4 = 4\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0117941","time":"2026-07-17T15:55:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"아닌가보네요.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117942","time":"2026-07-17T15:55:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"이대로 걸어서 가다보면 마을이 하나 있다고 들었다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117943","time":"2026-07-17T15:56:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"밤이 되더라도 갈 곳은 있으니 너무 조급해하지 않아도 좋다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117944","time":"2026-07-17T15:56:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"오호.. 알겠습니다, 헹헹.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117945","time":"2026-07-17T15:57:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그러고보니 이 곳에 와본 적이 있나?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117946","time":"2026-07-17T15:57:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"이 곳은 골기아 수도에서 보이는 바위산으로. 반나절 정도 걷다보면 다다를 수 있는 곳입니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117947","time":"2026-07-17T15:57:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"아뇨, 아무래도 완전 처음입니다. 웬만해선 전 모든 곳이 다 처음이죠. 어딜 잘 안 돌아다니는게 습관화 되어서.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117948","time":"2026-07-17T15:58:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"의뢰 같은 일 말곤 딱히 돌아다니는 일이 없네요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117949","time":"2026-07-17T15:59:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"나도 비슷하다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117950","time":"2026-07-17T15:59:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"길드에 들어온 이후에 의뢰가 아니면 어디 가지 않았으니까.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117951","time":"2026-07-17T16:00:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"조는 이리저리 경치를 둘러보다, 하늘도 한번 쳐다보며 시원한 바람을 느낍니다.\n\n\"오오, 이렇게 올라탄 상태로 하늘 보니까 뭔가, 느낌이 신기해요! 조금 무섭기도 하면서? 어린아이가 된 기분 같기도!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117952","time":"2026-07-17T16:00:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그만 내려와도 좋다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117953","time":"2026-07-17T16:00:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"꽃이 보일 때 집으면 되는거니까.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117954","time":"2026-07-17T16:00:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"앗, 헹헹. 그러죠.\"\n조심조심 코난의 어깨에서 내려옵니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117955","time":"2026-07-17T16:01:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"한바퀴 둘러본다는 생각으로 걷지. 어쩌면 밤을 지샐만한 곳을 찾는 것도 좋다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117956","time":"2026-07-17T16:01:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"이런 데에도 몬스터라든가, 그런 녀석들이 살까요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117957","time":"2026-07-17T16:01:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"이런 인적이 없는 곳에서 모닥불을 피우면 위험하기도 하고. 너만 괜찮다면 마을도 들리지 않고 어디 동굴 안에서 슬쩍 하루를 보내는게 더 나을 것 같다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117958","time":"2026-07-17T16:02:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"사람은 생각보다 믿을게 못 되니까.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117959","time":"2026-07-17T16:02:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"으흠.. 전 상관없습니다!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117960","time":"2026-07-17T16:03:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"좋다. 마저 찾아보지.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117961","time":"2026-07-17T16:03:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117962","time":"2026-07-17T16:03:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 1 = 1\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0117963","time":"2026-07-17T16:03:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"그렇게 코난과 아마이 조는 밤이 될 때까지 찾아다녔지만 꽃을 찾아내지 못 했습니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117964","time":"2026-07-17T16:04:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"벌써 어둑어둑해졌군요..\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117965","time":"2026-07-17T16:04:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"슬슬 아까 봐둔 골짜기로 간다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117966","time":"2026-07-17T16:04:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"더 어두워져서 보이지 않으면 발을 잘못 움직이다가 아래로 떨어진다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117967","time":"2026-07-17T16:04:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"너는 모르겠지만 나는 죽는다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117968","time":"2026-07-17T16:05:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 얼른 가보죠!\"\n둘은 골짜기로 발걸음을 옮깁니다~","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117969","time":"2026-07-17T16:06:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 아마이와 같이 바위산 한켠에 잘 보이지 않는 곳에 위치한 골짜기로 슬쩍 들어갔습니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117970","time":"2026-07-17T16:06:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"이렇게 불편하게 밤을 보내게 하는 것 같아 미안하다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117971","time":"2026-07-17T16:06:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"분명 의뢰주가 많이 보인다고 했는데 생각보다 그렇지 않은 것 같다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117972","time":"2026-07-17T16:06:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"이건 내가 조금 따져보도록 하겠다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117973","time":"2026-07-17T16:07:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"아이, 괜찮아요! 전 어디서나 잘 잘 수 있걸랑요. 헹헹, 의뢰비나 아마이징하게 받자구요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117974","time":"2026-07-17T16:07:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"음... 혹시 졸린가? 불침번을 서로 서야하니까 피곤하면 먼저 자도 좋다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117975","time":"2026-07-17T16:07:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"아니면 조금 이야기 하다가 자도 좋다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117976","time":"2026-07-17T16:08:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"전 언데드가 되고 나서, 지루할 땐 있었어도 졸린 적은 없었어요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117977","time":"2026-07-17T16:09:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"대충 아무데나 앉고선 등을 벽에 기댑니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117978","time":"2026-07-17T16:09:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"코난 씨가 피곤하시면 먼저 주무시고, 아니면 이야기나 할까요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117979","time":"2026-07-17T16:09:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"좋다. 나도 굳이 이 곳에서 많이 잘 생각은 없다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117980","time":"2026-07-17T16:10:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"날이 밝는대로 몸을 움직이고 길드 하우스에서 자는게 더 나으니까.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117981","time":"2026-07-17T16:10:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그나저나 언데드란 신기한 족속들이다. 잠을 자지 않는 것인가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117982","time":"2026-07-17T16:11:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"끼릭끼릭. 어깨를 돌리며 말합니다.\n\"사실 저도 잘 몰라요. 처음 언데드가 되고 나선 너무 무서워서 잠이 안 오는 건지, 언데드라 잠이 안 오는 건지 구분을 못했었는데...\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117983","time":"2026-07-17T16:12:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"음... 죽었을 때 기분은 어땠나? 그리고 다시 되살아 났을 때는?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117984","time":"2026-07-17T16:12:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그리고 죽고나서 어디로 갔는가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117985","time":"2026-07-17T16:14:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"뭐, 죽었을 때야 당연히 여럿 부정적인 생각들밖에 안 들었죠. 그때 가까운 사람들도 동시에 많이 잃었어서! 다시 되살아났을 때도 그리 좋은 상황은 아녔죠.\"\n잠시 기개를 살짝 기울이며 고민하다 다시 입을 엽니다.\n\"뭐, 여튼 어찌저찌 그때 관련 일을 해결하고 나서, 여기로 오게 됬죠. 갈 곳도 없었고!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117986","time":"2026-07-17T16:15:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"아, 미안하다. 미안한 부분은 두가지다. 하나는 나쁜 기억을 떠올리게 한 것. 둘은 질문이 잘못된 것이다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117987","time":"2026-07-17T16:15:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"나는 정말로 [죽음]이라는 것에 대한 질문이었다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117988","time":"2026-07-17T16:15:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"사람이 죽으면 어떻게되는지. 그것이 궁금했다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117989","time":"2026-07-17T16:15:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"느엥. 아아~\"\n멈칫했다가 이내 질문의 의도를 파악한 듯 고갤 끄덕입니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117990","time":"2026-07-17T16:16:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"음... 당장 이야기를 하자니 너무 난해한 것 같아서 나의 이야기를 조금 하겠다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117991","time":"2026-07-17T16:16:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"아마이 조가 코난 쪽으로 몸을 기울입니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0117992","time":"2026-07-17T16:16:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"고향. 로운델보다 더 멀리 있는 서쪽 끝의 절벽을 건너면 나타나는 곳에 위치한다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117993","time":"2026-07-17T16:17:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"절벽 속 작은 분지에서 살아가고 있었다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117994","time":"2026-07-17T16:17:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"나의 부족. 사람이 죽으면 동쪽, 해가 떠오르는 방향에 있는 죽은자들의 세상에 모인다고 했다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117995","time":"2026-07-17T16:17:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"나는 궁금했다, 나의 여동생이 죽고서 죽은 자의 세상으로 가면 다시 여동생을 만날 수 있을지.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117996","time":"2026-07-17T16:18:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"하지만 동쪽, 새로운 세상과 사람들이 있을 뿐이다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117997","time":"2026-07-17T16:18:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그렇기에 더욱 궁금하다. 죽음이라는 것은 무엇인가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117998","time":"2026-07-17T16:18:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그 개념을 어떻게 받아들여야하는가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0117999","time":"2026-07-17T16:18:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"직접 겪은 너에게 물어보고 싶었다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118000","time":"2026-07-17T16:19:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"흐으으음~~\"\n의외로, 엄청나게 철학적인 면모를 보여주는 코난의 말에 깊게 고민합니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118001","time":"2026-07-17T16:19:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"히야~ 이렇게나 깊은 질문을 하실 줄이야. 역시 겉만 보고 판단하면 안 되는군요..\"\n작게 혼잣말을 중얼거립니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118002","time":"2026-07-17T16:20:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그런 소리 많이 듣는다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118003","time":"2026-07-17T16:20:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"이해한다. 나, 야만인 출신이다. 너희들과 많이 다르다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118004","time":"2026-07-17T16:20:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"고로 공부한다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118005","time":"2026-07-17T16:23:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그래서 어떤가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118006","time":"2026-07-17T16:23:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"죽음은, 애벌레가 나비로 변하는 것과 비슷하다고 생각해요. 저희처럼 살아있는, 즉 애벌레는 땅에서만 살 수 있으니, 이미 죽은 사람들인, 날아다니는 나비를 만날 수는 없어요. 하지만 땅 위에 나비의 그림자가 존재하듯, 그들은 떠난 후에도 계속 우리에게 남아있고. 저희도 나비가 되면 다시 만날 수 있지 않을까요?\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118007","time":"2026-07-17T16:23:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"저같은 경우는 아마 억지로 다시 애벌레가 된 느낌. 언데드에 관해선 잘 모르겠네요, 헹헹.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118008","time":"2026-07-17T16:23:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"무슨 느낌인지 모르겠지만 알겠다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118009","time":"2026-07-17T16:23:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"애벌레, 즉 산 자는 이해할 수 없는 개념이고\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118010","time":"2026-07-17T16:24:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"나비, 죽은 자만 느낄 수 있다는 말인건가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118011","time":"2026-07-17T16:24:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"잘 와닿지는 않지만. 대답해줘서 고맙다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118012","time":"2026-07-17T16:24:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"기억해두고 여러 언데드들의 의견을 모아 정리해보겠다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118013","time":"2026-07-17T16:25:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 굉장히 멋진 일을 하시는 것 같군요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118014","time":"2026-07-17T16:25:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그런가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118015","time":"2026-07-17T16:25:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"잘 모르겠다. 대부분의 사람들은 나와 대화하다보면 답답해했다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118016","time":"2026-07-17T16:25:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"몸은 큰데 어린아이같은 질문은 한다고 한다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118017","time":"2026-07-17T16:27:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"흐음, 전 그런게 오히려 좋은 것 같아요. 어른들은, 이렇게 말하면 조금 욕하는 것처럼 들릴 수도 있지만, 마치 눈이 먼 사람들 같을 때가 있어요.\n전 그런 근본적인 질문들이 맘에 드네요. 어떻게 잘 사느냐 보단 왜 사느냐, 그런 사고방식 말이에요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118018","time":"2026-07-17T16:27:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"다음엔 또 뭘 먹을까를 궁리하는 것보단 다른 사람은 잘 먹나, 그런걸 생각하는..\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118019","time":"2026-07-17T16:28:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"흠... 이런말 하기는 좀 그렇지만.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118020","time":"2026-07-17T16:28:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"방금 예시만 듣고서는 삶이 피곤할 것 같다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118021","time":"2026-07-17T16:28:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"무슨말을 하는지는 알겠다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118022","time":"2026-07-17T16:28:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 낄낄 거리면서 이야기합니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118023","time":"2026-07-17T16:29:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"케헥, 헹헹헹.\"\n아마이 조도 괜시리 뒷목을 매만지며 웃습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118024","time":"2026-07-17T16:29:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"너무 내 이야기만 한 것 같다. 뭐, 말하고 싶은 이야기가 있나?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118025","time":"2026-07-17T16:30:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"흐음~ 글쎄요. 할 얘기라 해봤자 더 이상 자기자랑밖에 할게 없달까요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118026","time":"2026-07-17T16:30:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"자존감이 높은 편이다. 좋다고 생각한다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118027","time":"2026-07-17T16:31:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"의기소침한 사람들은 보통 제 능력을 발휘하지 못 한다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118028","time":"2026-07-17T16:31:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"자신을 믿고 행동하는 것. 전사들이 할 덕목이다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118029","time":"2026-07-17T16:31:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 그렇다면야! 제가 안 그래도 최근 의뢰 때 아주 멋진 활약을 펼쳤다구요!\"\n금세 신나서 들뜬 채 얘기하기 시작합니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118030","time":"2026-07-17T16:32:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 그 이야기를 묵묵히 듣고 있습니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118031","time":"2026-07-17T16:32:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"군주 벌이라는 흉악한 몬스터와 싸웠는데, 족히 코난 씨만큼은 될만한 거대한 벌이었어요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118032","time":"2026-07-17T16:32:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"꿀을 제법 많이 만들겠는데.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118033","time":"2026-07-17T16:33:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"심지어 거긴 마을 한복판이라, 마을 사람들이 위험했고!! 심지어 근처에 자기도 모험가라며 나선, 마법을 쓸 줄 아는 어린 소녀까지 있었죠!!\"\n과장된 몸짓을 하며, 얼마나 중대한 상황이었는지 마구마구 말을 뱉어냅니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118034","time":"2026-07-17T16:34:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"오, 잡아냈나?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118035","time":"2026-07-17T16:34:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"설상가상으로 제 특기인 줄을 묶은 단검을 쓰는 기술을 쓰지 못하는 상황이었어요, 줄이 끊어져버렸거든요..!!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118036","time":"2026-07-17T16:35:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"계속 말해봐라.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118037","time":"2026-07-17T16:35:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"그래서 녀석이 소녀를 향해 달려드는 바로 그 순간!! 제가 단검을 던져서 녀석의 한쪽 날개를 부우욱 찢어냈죠!!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118038","time":"2026-07-17T16:36:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"벌레들은 보통 날개만 찢으면 잡기 쉽기는 하지.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118039","time":"2026-07-17T16:36:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"소녀는 지켜냈지만, 문제는 그 후였어요. 녀석의 태클을 직격으로 맞아서 갈비뼈가 다 부러진 채 벽에 처박혔죠.\"\n붕대를 칭칭 감은 자신의 갈비뼈를 보여줍니다.\n\"이게 바로 그때의 영광의 상처랄까요!\"\n자랑하듯 으쓱거리며 얘기합니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118040","time":"2026-07-17T16:36:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"소녀랑은 어떻게 되는 중인가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118041","time":"2026-07-17T16:38:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헤엥, 저같은 뼉다구가 멀쩡하고 창창한 애 앞날을 막을 순 없죠. 녀석은 멀쩡한 남자랑 만나야 해요..\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118042","time":"2026-07-17T16:38:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"반박은 어렵군.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118043","time":"2026-07-17T16:38:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그나저나 사람만한 벌이 나타나서 마을의 사람을 덮치다니.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118044","time":"2026-07-17T16:39:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"살기 좋은 동네는 아닌 것 같다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118045","time":"2026-07-17T16:39:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"여튼, 전 부들거리는 몸을 이끌고 일어서서, 소녀에게 머리끈을 받고! 그걸 줄로 이용해서 제 필살기를 쓰는 데 성공했습니다.. 머리끈을 받을 때 변태라는 이상한 소릴 듣긴 했습니다만. 아, 이게 중요한게 아니지.\"\n횡설수설 얘길 하며 손을 휘적거립니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118046","time":"2026-07-17T16:40:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"음....\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118047","time":"2026-07-17T16:40:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"그래서 군주 벌은 쓰러졌고, 전 그대로 기절했죠. 깨어나보니 소녀가 절 간호하고 있었더군요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118048","time":"2026-07-17T16:40:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"오...\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118049","time":"2026-07-17T16:40:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"음...\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118050","time":"2026-07-17T16:40:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 왜 그러시죠.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118051","time":"2026-07-17T16:40:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"상황이 묘할 것 같아서 그런다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118052","time":"2026-07-17T16:40:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"해골을 간호하는 상황이라면...\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118053","time":"2026-07-17T16:40:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"기괴하지 않은가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118054","time":"2026-07-17T16:41:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"뭐, 그 소녀가 담력이 대단한 것 같더라구요. 다짜고짜 나타나서 군주 벌에게 마법 공격을 하기도 했으니.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118055","time":"2026-07-17T16:41:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"게다가... 뭔가 소녀와 잘 지내는 이야기도 기대했건만... 상황이 여의치 않다는 아쉬움도 있다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118056","time":"2026-07-17T16:41:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"좀 기괴하긴 하네요, 헹헹.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118057","time":"2026-07-17T16:41:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"흥미롭지만 재미는 애매한 이야기다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118058","time":"2026-07-17T16:42:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"뭐, 한번 편지를 받긴 했습니다.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118059","time":"2026-07-17T16:42:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"오, 어떤가? 뭔가 좋은 징조가 보이는가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118060","time":"2026-07-17T16:42:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"자기 활약이 크나 큰 역할을 했지만, 해골 씨도 여튼 잘했다고, 자기도 모험가가 될 거라고.. 그런 얘기더군요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118061","time":"2026-07-17T16:43:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"좋은 징조라니, 연애 얘기 하시는 건 아니죠 설마? 헹헹.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118062","time":"2026-07-17T16:43:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"왜 아니겠나?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118063","time":"2026-07-17T16:43:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"힘들고 어렵지겠지만.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118064","time":"2026-07-17T16:43:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"시도조차 하지 않는 것 보다야 낫겠지.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118065","time":"2026-07-17T16:44:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"다만, 어디까지나 나의 의견이다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118066","time":"2026-07-17T16:44:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"스스로 원하는 것을 하는 것이 가장 중요하다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118067","time":"2026-07-17T16:44:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"어쩌면 놀랍도록 멋진 모험가가 되어. 유명세를 가진 후에는.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118068","time":"2026-07-17T16:44:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"또 모르지 않겠는가?\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118069","time":"2026-07-17T16:44:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 뭐, 글쎄요. 그때 가서 알겠죠.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118070","time":"2026-07-17T16:45:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"적어도 지금은 잘 모르겠네요~\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118071","time":"2026-07-17T16:45:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그래, 좋다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118072","time":"2026-07-17T16:45:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"나는 슬슬 눈을 좀 붙이겠다.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118073","time":"2026-07-17T16:45:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"혹여나 자고 싶다면 말을 해라.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118074","time":"2026-07-17T16:46:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"헹헹, 그럼 먼저 주무시고 계세요.\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0118075","time":"2026-07-17T16:46:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그래.\"","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118076","time":"2026-07-17T16:46:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 그렇게 잠에 들었고.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118077","time":"2026-07-17T16:46:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"아마이 조는 밤 하늘을 보면서 불침번을 했겠네요.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118078","time":"2026-07-17T16:47:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"아침에 눈을 뜨자. 자리잡은 동굴 안 골짜기 안에 찾던 꽃이 있었습니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118079","time":"2026-07-17T16:47:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난과 아마이 조는 그대로 골기아 수도로 돌아왔고.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118080","time":"2026-07-17T16:47:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"코난은 불침번을 세운 것이 좀 미안했는지 아마이 조에게 웃돈을 더 넘겼습니다.","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118081","time":"2026-07-17T16:47:00+09:00","room":"RP II","name":"코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-96ee3cc09ac8"]},{"id":"RP-II-0118082","time":"2026-07-17T16:47:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
